import sys

def parse_range(item):
    parts = item.split('-')
    if len(parts) == 2:
        return int(parts[0]), int(parts[1])
    elif len(parts) == 3:
        if parts[0] == '':
            return -int(parts[1]), int(parts[2])
        else:
            return int(parts[0]), -int(parts[2])
    elif len(parts) == 4:
        return -int(parts[1]), -int(parts[3])
    else:
        raise ValueError("Invalid range format")

